<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import AdminDialog from '../../AdminDialog.vue';
import Pagination from '../../CvBankPagination.vue';
const props=defineProps<{data:any;csrf?:string}>();const emit=defineEmits(['changed']);
const tab=ref('departments'),company=ref(''),search=ref(''),page=ref(1),size=ref(12),editing=ref(''),form=ref<any>({}),busy=ref(false),error=ref(''),message=ref('');
const roles:Record<string,string>={employee:'Employee',pm:'Project Manager',om:'Operations Manager',hr:'Human Resources',ceo:'CEO',md:'Managing Director',company_admin:'Company Admin'};
const rows=computed(()=>(tab.value==='departments'?props.data.daymark_departments:props.data.daymark_roles||[]).filter((row:any)=>(!company.value||row.company_id===Number(company.value))&&row.name.toLowerCase().includes(search.value.toLowerCase())));
const paged=computed(()=>rows.value.slice((page.value-1)*size.value,page.value*size.value));
const available=computed(()=>props.data.daymark_role_matrix?.roles.find((r:any)=>r.role===form.value.base_role)?.permissions||[]);
watch([company,search,tab],()=>page.value=1);
function open(kind:string,row:any=null){error.value='';editing.value=kind;form.value=row?{...row,permissions:[...(row.permissions||[])]}:{company_id:Number(company.value)||props.data.companies[0]?.id||'',name:'',base_role:'employee',permissions:['view_reports','write_reports','export_reports','view_companies']};if(kind==='delete')form.value.replacement_id=null;}
async function save(path:string){busy.value=true;error.value='';try{const r=await fetch('/admin/api/daymark/'+path,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify(form.value)});const result=await r.json();if(!r.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message);message.value=result.message||'Daymark setup saved.';editing.value='';emit('changed');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
const companyName=(id:number)=>props.data.companies.find((c:any)=>c.id===id)?.name||'Company';
</script>
<template><div class="daymark-admin"><div class="admin-section-heading"><div><h2>Daymark setup</h2><p class="muted">Manage reporting departments and roles. Companies, employee access and invitations use the shared administration sections.</p></div><a class="button" href="/daymark">Open Daymark</a></div>
<div class="daymark-admin-links"><a class="button" href="/admin#companies">Companies</a><a class="button" href="/admin#users">Employee access &amp; managers</a><a class="button" href="/admin#invitations">Invitations</a></div>
<div class="daymark-admin-tabs" role="tablist" aria-label="Daymark setup"><button v-for="key in ['departments','roles']" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="tab=key">{{key==='departments'?'Departments':'Roles & permissions'}}</button></div>
<p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error&&!editing" class="notice admin-error" role="alert">{{error}}</p>
<div class="admin-section-heading"><h3>{{tab==='departments'?'Reporting departments':'Custom reporting roles'}}</h3><button class="button primary" @click="open(tab==='departments'?'department':'role')">{{tab==='departments'?'Add department':'Create role'}}</button></div>
<div class="daymark-admin-filters"><label>Company<select v-model="company" aria-label="Setup company"><option value="">All companies</option><option v-for="c in data.companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label>Search<input type="search" v-model="search" placeholder="Search by name"></label></div>
<div class="admin-table-scroll"><table class="admin-user-table"><thead><tr><th>Name</th><th>Company</th><th v-if="tab==='roles'">Base role</th><th>Actions</th></tr></thead><tbody><tr v-for="row in paged" :key="row.id"><td><strong>{{row.name}}</strong></td><td>{{companyName(row.company_id)}}</td><td v-if="tab==='roles'">{{roles[row.base_role]}}</td><td><button v-if="tab==='roles'" class="button" @click="open('role',row)">Edit role</button><button v-else class="button admin-danger" @click="open('delete',row)">Delete department</button></td></tr><tr v-if="!rows.length"><td :colspan="tab==='roles'?4:3" class="empty-state">{{tab==='departments'?'No departments match this selection.':'No custom roles. Built-in reporting roles are available in employee access.'}}</td></tr></tbody></table></div>
<Pagination v-model:page="page" v-model:page-size="size" :total="rows.length"/>
<section v-if="tab==='roles'" class="admin-editor"><h3>Built-in data scopes</h3><p class="muted">Employees see their own reports. PM/OM see their assigned people. Company Admin, CEO, MD and HR see their reporting company. Judibas administrators oversee every company.</p><p class="muted">Company, department, role and invitation setup is managed by Judibas administrators here. Reporting roles do not grant access to the shared Admin dashboard.</p></section>
<AdminDialog v-if="editing" :title="editing==='department'?'Add Daymark department':editing==='delete'?'Delete Daymark department':form.id?'Edit reporting role':'Create reporting role'" :busy="busy" @close="editing=''"><form class="admin-editor" @submit.prevent="save(editing==='department'?'departments':editing==='delete'?'departments/delete':'roles')"><p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<template v-if="editing==='delete'"><p>Delete <strong>{{form.name}}</strong>? Select a replacement if people or pending invitations use this department.</p><label>Replacement department<select v-model.number="form.replacement_id"><option :value="null">No replacement</option><option v-for="d in data.daymark_departments.filter((d:any)=>d.company_id===form.company_id&&d.id!==form.id)" :key="d.id" :value="d.id">{{d.name}}</option></select></label></template>
<template v-else><label>Company<select v-model.number="form.company_id" required :disabled="!!form.id"><option v-for="c in data.companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{editing==='department'?'Department name':'Role name'}}<input v-model="form.name" required :maxlength="editing==='department'?200:100"></label><template v-if="editing==='role'"><label>Base role<select v-model="form.base_role" :disabled="!!form.id" @change="form.permissions=['view_reports']"><option v-for="(label,key) in roles" :key="key" :value="key">{{label}}</option></select></label><p class="muted">Custom roles can restrict their base role but cannot expand its reporting scope. Shared administration stays with Judibas administrators.</p><fieldset><legend>Reporting permissions</legend><label class="check" v-for="key in available.filter((key:string)=>!['manage_companies','manage_departments','manage_invitations','manage_people','manage_roles','manage_settings'].includes(key))" :key="key"><input type="checkbox" v-model="form.permissions" :value="key">{{data.daymark_role_matrix.abilities[key]}}</label></fieldset></template></template><div class="editor-actions"><button class="button primary" :disabled="busy">{{editing==='delete'?'Delete department':'Save changes'}}</button><button type="button" class="button" :disabled="busy" @click="editing=''">Cancel</button></div></form></AdminDialog>
</div></template>
<style scoped>.daymark-admin-links{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.daymark-admin-tabs{display:flex;gap:6px;padding:5px;border:1px solid var(--line);background:var(--rail);border-radius:10px;width:fit-content;margin:24px 0}.daymark-admin-tabs button{border:0;background:none;color:var(--muted);font:inherit;padding:10px 16px;border-radius:7px;cursor:pointer}.daymark-admin-tabs button.active{background:#7665ed20;color:#7665ed}.daymark-admin-filters{display:flex;gap:16px;margin:20px 0}.daymark-admin-filters label{display:grid;gap:8px;flex:1;font-size:12px}.daymark-admin-filters input,.daymark-admin-filters select{padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text);font:inherit;width:100%}@media(max-width:600px){.daymark-admin-filters{flex-direction:column}}</style>
